        "fahren використовується під час подорожі auto, автобусом, поїздом, велосипедом або іншим транспортним засобом.",
        "Якщо в реченні є особа як об’єкт, fahren може означати вести або відводити.",
        "Якщо рух відбувається пішки, зазвичай використовуються gehen або laufen."
