      "translation": "в • до",
      "explanation": [
        "Головна думка: in зазвичай означає в або до місця, коли йдеться про кімнату, країну, місто чи будівлю.",
        "З розташуванням in часто перекладається як у або в: in Berlin = у Берліні.",
        "При русі in означає всередину: ins Kino = до kino.",
        "Латиський переклад змінюється залежно від контексту."
      ],
