      "translation": "звичайно • природний",
      "explanation": [
        "Головна думка: natürlich як прислівник означає звичайно, як прикметник означає природний.",
        "У розмові, підтверджуючи щось, natürlich = звичайно (Kommst du mit? – Natürlich! = Ви йдете? – Звичайно!).",
        "Говорячи про природу, походження або якості, natürlich = природне (natürliche Schönheit = природна краса).",
        "Контекст (відповідь/підтвердження або опис) показує правильне значення."
      ],
